create extension if not exists pgcrypto;
create type public.content_status as enum ('draft','published','archived');
create table public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table public.profiles(id uuid primary key default gen_random_uuid(),full_name text not null,headline text not null,summary text not null,email text,location text,availability text,avatar_url text,resume_url text,github_url text,linkedin_url text,website_url text,updated_at timestamptz not null default now());
create table public.projects(id uuid primary key default gen_random_uuid(),title text not null,slug text not null unique,summary text not null,problem text,solution text,architecture text,challenges text,outcomes text,repository_url text not null,demo_url text,category text not null,status public.content_status not null default 'draft',featured boolean not null default false,sort_order integer not null default 0,technologies text[] not null default '{}',started_at date,completed_at date,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint project_repo_https check(repository_url like 'https://%'),constraint project_demo_https check(demo_url is null or demo_url like 'https://%'));
create table public.skills(id uuid primary key default gen_random_uuid(),name text not null unique,category text not null,proficiency_label text,sort_order integer not null default 0);
create table public.project_technologies(project_id uuid not null references public.projects(id) on delete cascade,skill_id uuid not null references public.skills(id) on delete cascade,primary key(project_id,skill_id));
create table public.experience(id uuid primary key default gen_random_uuid(),company text not null,role text not null,location text,employment_type text,description text,achievements text[] not null default '{}',start_date date not null,end_date date,is_current boolean not null default false,status public.content_status not null default 'published',sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint experience_dates check(end_date is null or end_date>=start_date),constraint current_role_date check(not is_current or end_date is null));
create table public.education(id uuid primary key default gen_random_uuid(),institution text not null,qualification text not null,field_of_study text,location text,start_date date,end_date date,details text,sort_order integer not null default 0);
create table public.project_images(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete cascade,storage_path text not null,alt_text text not null,caption text,sort_order integer not null default 0);
create table public.site_settings(key text primary key,value jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create table public.contact_messages(id uuid primary key default gen_random_uuid(),sender_name text not null check(length(sender_name) between 1 and 100),sender_email text not null check(length(sender_email)<=254),subject text,message text not null check(length(message) between 10 and 5000),status text not null default 'unread' check(status in ('unread','read','archived')),created_at timestamptz not null default now());
create index projects_publication_order_idx on public.projects(status,featured,sort_order);create index experience_publication_order_idx on public.experience(status,sort_order);create index project_images_order_idx on public.project_images(project_id,sort_order);
create or replace function public.is_portfolio_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.admin_users where user_id=auth.uid()); $$;
revoke all on function public.is_portfolio_admin() from public;grant execute on function public.is_portfolio_admin() to authenticated;
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now();return new;end; $$;
create trigger profiles_updated_at before update on public.profiles for each row execute function public.set_updated_at();create trigger projects_updated_at before update on public.projects for each row execute function public.set_updated_at();create trigger experience_updated_at before update on public.experience for each row execute function public.set_updated_at();create trigger settings_updated_at before update on public.site_settings for each row execute function public.set_updated_at();
alter table public.admin_users enable row level security;alter table public.profiles enable row level security;alter table public.projects enable row level security;alter table public.skills enable row level security;alter table public.project_technologies enable row level security;alter table public.experience enable row level security;alter table public.education enable row level security;alter table public.project_images enable row level security;alter table public.site_settings enable row level security;alter table public.contact_messages enable row level security;
create policy "Admins can read admin allowlist" on public.admin_users for select to authenticated using (user_id=auth.uid());
create policy "Public reads profile" on public.profiles for select to anon,authenticated using (true);create policy "Admins manage profile" on public.profiles for all to authenticated using (public.is_portfolio_admin()) with check (public.is_portfolio_admin());
create policy "Public reads published projects" on public.projects for select to anon,authenticated using (status='published' or public.is_portfolio_admin());create policy "Admins manage projects" on public.projects for all to authenticated using (public.is_portfolio_admin()) with check (public.is_portfolio_admin());
create policy "Public reads skills" on public.skills for select to anon,authenticated using (true);create policy "Admins manage skills" on public.skills for all to authenticated using (public.is_portfolio_admin()) with check (public.is_portfolio_admin());
create policy "Public reads project technology links" on public.project_technologies for select to anon,authenticated using (exists(select 1 from public.projects p where p.id=project_id and (p.status='published' or public.is_portfolio_admin())));create policy "Admins manage project technology links" on public.project_technologies for all to authenticated using (public.is_portfolio_admin()) with check (public.is_portfolio_admin());
create policy "Public reads published experience" on public.experience for select to anon,authenticated using (status='published' or public.is_portfolio_admin());create policy "Admins manage experience" on public.experience for all to authenticated using (public.is_portfolio_admin()) with check (public.is_portfolio_admin());
create policy "Public reads education" on public.education for select to anon,authenticated using (true);create policy "Admins manage education" on public.education for all to authenticated using (public.is_portfolio_admin()) with check (public.is_portfolio_admin());
create policy "Public reads published project images" on public.project_images for select to anon,authenticated using (exists(select 1 from public.projects p where p.id=project_id and (p.status='published' or public.is_portfolio_admin())));create policy "Admins manage project images" on public.project_images for all to authenticated using (public.is_portfolio_admin()) with check (public.is_portfolio_admin());
create policy "Public reads settings" on public.site_settings for select to anon,authenticated using (key in ('public_profile','social_links','contact'));create policy "Admins manage settings" on public.site_settings for all to authenticated using (public.is_portfolio_admin()) with check (public.is_portfolio_admin());
create policy "Admins read messages" on public.contact_messages for select to authenticated using (public.is_portfolio_admin());create policy "Admins update messages" on public.contact_messages for update to authenticated using (public.is_portfolio_admin()) with check (public.is_portfolio_admin());
-- Contact submissions go through the server endpoint. This policy permits anon INSERT only; no public SELECT.
-- No public INSERT policy: the validated server endpoint uses a server-only service key to insert messages.

-- Create the portfolio-media bucket in Storage dashboard (public bucket for published images only).
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('portfolio-media','portfolio-media',true,5242880,array['image/jpeg','image/png','image/webp','application/pdf']) on conflict(id) do nothing;
create policy "Public reads portfolio media" on storage.objects for select to anon,authenticated using (bucket_id='portfolio-media');create policy "Admins upload portfolio media" on storage.objects for insert to authenticated with check (bucket_id='portfolio-media' and public.is_portfolio_admin());create policy "Admins update portfolio media" on storage.objects for update to authenticated using (bucket_id='portfolio-media' and public.is_portfolio_admin()) with check (bucket_id='portfolio-media' and public.is_portfolio_admin());create policy "Admins delete portfolio media" on storage.objects for delete to authenticated using (bucket_id='portfolio-media' and public.is_portfolio_admin());
